const fs=require('node:fs');
const ids={Pikachu:'025',Charmander:'004',Squirtle:'007',Blastoise:'009',Charizard:'006',Venusaur:'003'};
(async()=>{await Promise.all(Object.entries(ids).map(async([name,id])=>{const response=await fetch(`https://raw.githubusercontent.com/06wj/pokemon/master/public/models/${id}/model.glb`);if(!response.ok)throw Error(name+': '+response.status);const buf=Buffer.from(await response.arrayBuffer());fs.writeFileSync(`assets/models/${name}.glb`,buf);const json=JSON.parse(buf.subarray(20,20+buf.readUInt32LE(12)).toString());console.log(name,buf.length,'bytes',JSON.stringify({animations:json.animations?.map(a=>({name:a.name,channels:a.channels.length})),skins:json.skins?.length,meshes:json.meshes?.length,extensions:json.extensionsUsed}));}));})().catch(e=>{console.error(e);process.exit(1)});
